WITH with_windows AS (SELECT id, customer_id, store_id, status, CORR(shipping_fee, amount) OVER (PARTITION BY channel) corr_shipping_fee_amount, DENSE_RANK() OVER (PARTITION BY YEAR(order_date), customer_id ORDER BY shipping_fee DESC) shipping_fee_dense_rank, NTILE(10) OVER (PARTITION BY channel, status ORDER BY discount, id) discount_bucket FROM orders WHERE order_date BETWEEN '2023-04-24' AND '2023-10-01') SELECT s.id, s.customer_id, s.status, s.corr_shipping_fee_amount, s.shipping_fee_dense_rank, s.discount_bucket, (SELECT MIN(a2.balance) FROM accounts a2 WHERE a2.customer_id = s.customer_id) AS min_account_balance FROM with_windows s ORDER BY min_account_balance DESC;
